    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_35, 'لماذا أحاط الإمام العسكري (ع) ولادة ابنه بالكتمان؟', '["لأنه كان مسافرًا خارج سامراء","خوفًا من طلب السلطة العباسية له","لأن الأسرة انتقلت إلى المدينة","لانقطاع الاتصال بأصحابه تمامًا"]'::jsonb, 1, 25, 7, 'multi', 'أُخفيت ولادته لشدة طلب السلطان له ومراقبته بيت الإمام العسكري.', 'الولادة والنشأة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_35, 'ماذا فعل الإمام العسكري (ع) لإثبات ولادة ابنه لبعض ثقاته؟', '["أراه لعدد من أصحابه الخواص","أعلنه على منبر بغداد","أرسله إلى المدينة علنًا","سجله لدى ديوان الخلافة"]'::jsonb, 0, 20, 8, 'multi', 'عرض الإمام العسكري ابنه على جماعة مختارة من أصحابه وعرّفهم إمامهم بعده.', 'الولادة والنشأة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_35, 'كم كان عمر الإمام المهدي (عج) تقريبًا عند بدء إمامته سنة 260هـ؟', '["عشر سنوات","خمس عشرة سنة","خمس سنوات","عشرون سنة"]'::jsonb, 2, 20, 9, 'multi', 'وُلد سنة 255هـ وبدأت إمامته بعد أبيه سنة 260هـ، فكان عمره نحو خمس سنوات.', 'بدء الإمامة');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
