    RETURNING id INTO v_lib_id_179;

    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_179, 'ما اسم الأسرة الحاكمة التي أسّست إمبراطورية فارسية عظيمة امتدت من مصر إلى الهند، وكان من أبرز ملوكها كورش الكبير؟', '["الأسرة الساسانية","الأسرة الأخمينية","الأسرة البارثية","الأسرة السلوقية"]'::jsonb, 1, 25, 0, 'multi', 'الأسرة الأخمينية (550-330 ق.م) أسسها كورش الكبير وبنت أوسع إمبراطورية في العالم القديم امتدت من مصر واليونان حتى الهند.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_179, 'البتراء الأردنية كانت عاصمة مملكة الأنباط قبل الفتح الروماني.', '["صح","خطأ"]'::jsonb, 0, 25, 1, 'boolean', 'كانت البتراء عاصمة المملكة النبطية التي ازدهرت بين القرنين الرابع قبل الميلاد والثاني الميلادي، قبل أن يضمها الرومان عام 106م.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_179, 'ما اسم القائد العثماني الذي فتح القسطنطينية عام 1453م؟', '["سليمان القانوني","بايزيد الثاني","محمد الفاتح","سلجوق بك"]'::jsonb, 2, 25, 2, 'multi', 'قاد السلطان العثماني محمد الثاني الملقب بالفاتح حملة فتح القسطنطينية عام 1453م، وبذلك أسقط الإمبراطورية البيزنطية.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
    VALUES (v_lib_id_179, 'في أي عام تأسست جامعة الدول العربية؟', '["1943","1945","1948","1950"]'::jsonb, 1, 25, 3, 'multi', 'تأسست جامعة الدول العربية في 22 مارس 1945م بالقاهرة بمشاركة سبع دول عربية مؤسِّسة.', '');
    INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
